// src/live/agents/posting-payloads.ts

import { NormalizedPayload } from "./posting"

interface BuildContext {
  topic: string
  baseVideoDir?: string
}

const DEFAULT_VIDEO_DIR = "C:/primordia/output"

// -----------------------------
// YouTube (long / standard)
// -----------------------------
export function buildYouTubePayload(ctx: BuildContext): NormalizedPayload {
  const dir = ctx.baseVideoDir || DEFAULT_VIDEO_DIR

  return {
    platform: "youtube",
    title: ctx.topic,
    description: [
      ctx.topic,
      "",
      "Generated by PrimordiaOS Monetization Engine.",
      "Exploring synthetic realms, load, entropy, and pressure."
    ].join("\n"),
    tags: ["primordiaos", "automation", "synthetic", "systems"],
    videoPath: `${dir}/primordia-youtube.mp4`
  }
}

// -----------------------------
// TikTok
// -----------------------------
export function buildTikTokPayload(ctx: BuildContext): NormalizedPayload {
  const dir = ctx.baseVideoDir || DEFAULT_VIDEO_DIR

  return {
    platform: "tiktok",
    caption: `${ctx.topic}\n\nPrimordiaOS live monetization engine in action.`,
    videoPath: `${dir}/primordia-tiktok.mp4`
  }
}

// -----------------------------
// Instagram Reels
// -----------------------------
export function buildInstagramPayload(ctx: BuildContext): NormalizedPayload {
  const dir = ctx.baseVideoDir || DEFAULT_VIDEO_DIR

  return {
    platform: "instagram",
    caption: `${ctx.topic}\n\nSynthetic realms • automation • PrimordiaOS.`,
    videoPath: `${dir}/primordia-instagram.mp4`
  }
}

// -----------------------------
// YouTube Shorts
// -----------------------------
export function buildShortsPayload(ctx: BuildContext): NormalizedPayload {
  const dir = ctx.baseVideoDir || DEFAULT_VIDEO_DIR

  return {
    platform: "shorts",
    title: `${ctx.topic} (Shorts)`,
    description: `Quick hit: ${ctx.topic}\n\nGenerated by PrimordiaOS.`,
    tags: ["shorts", "primordiaos", "automation"],
    videoPath: `${dir}/primordia-shorts.mp4`
  }
}

// -----------------------------
// Facebook Reels
// -----------------------------
export function buildFacebookPayload(ctx: BuildContext): NormalizedPayload {
  const dir = ctx.baseVideoDir || DEFAULT_VIDEO_DIR

  return {
    platform: "facebook",
    caption: `${ctx.topic}\n\nPrimordiaOS • synthetic monetization engine.`,
    videoPath: `${dir}/primordia-facebook.mp4`
  }
}

// -----------------------------
// X (Twitter)
// -----------------------------
export function buildXPayload(ctx: BuildContext): NormalizedPayload {
  return {
    platform: "x",
    text: `${ctx.topic} — generated by PrimordiaOS.\n\nSynthetic realms • load • entropy • pressure.`,
  } as any
}

// -----------------------------
// Reddit
// -----------------------------
export function buildRedditPayload(ctx: BuildContext): NormalizedPayload {
  return {
    platform: "reddit",
    title: ctx.topic,
    body: `PrimordiaOS generated this topic:\n\n${ctx.topic}\n\nDiscuss synthetic systems, automation, and monetization.`,
  } as any
}

// -----------------------------
// LinkedIn
// -----------------------------
export function buildLinkedInPayload(ctx: BuildContext): NormalizedPayload {
  return {
    platform: "linkedin",
    text: `${ctx.topic}\n\nPrimordiaOS explores synthetic operating systems and automated monetization workflows.`,
  } as any
}
